using System.Collections;
using LittleLeo.Variables;
using TMPro;
using UnityEngine;

namespace Astrea;

public class TooltipNameInstance : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private CanvasGroup canvasGroup;

	[SerializeField]
	private TextMeshProUGUI nameTooltipText;

	[Header("Animation")]
	[SerializeField]
	private float fadeDuration;

	[SerializeField]
	private AnimationCurve fadeCurve;

	[SerializeField]
	private FloatReference tooltipDelayReference;

	[Header("Character")]
	[SerializeField]
	private bool character;

	private Coroutine coroutine;

	private Coroutine delayToShowCoroutine;

	private bool isEnabled;

	private void Start()
	{
		if (ReferenceSingleton<LocalizationManager>.Instance.LocalizationTableLoaded && character)
		{
			Initialize(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.LocalizedCharacterName);
		}
	}

	public void Initialize(string name)
	{
		nameTooltipText.SetText(name);
	}

	private void OnEnable()
	{
		isEnabled = true;
	}

	private void OnDisable()
	{
		isEnabled = false;
	}

	public void Fade(bool value, bool withDelay)
	{
		if (!isEnabled)
		{
			return;
		}
		if (delayToShowCoroutine != null)
		{
			StopCoroutine(delayToShowCoroutine);
		}
		if (coroutine != null)
		{
			StopCoroutine(coroutine);
		}
		if (value)
		{
			if (withDelay)
			{
				delayToShowCoroutine = StartCoroutine(ShowCavasGroupWithDelay());
			}
			else
			{
				FadeCanvasGroup(value: true);
			}
		}
		else
		{
			FadeCanvasGroup(value: false);
		}
	}

	private IEnumerator ShowCavasGroupWithDelay()
	{
		yield return new WaitForSeconds(tooltipDelayReference.Value);
		FadeCanvasGroup(value: true);
	}

	private void FadeCanvasGroup(bool value)
	{
		coroutine = StartCoroutine(canvasGroup.FadeCanvasGroupCoroutine(fadeDuration, value ? 1 : 0, fadeCurve));
	}
}
